\set ON_ERROR_STOP on
begin;
set local search_path = public, extensions;
select no_plan();
insert into auth.users(id,email) values ('a6000000-0000-4000-8000-000000000001','push-a@example.test'),('a6000000-0000-4000-8000-000000000002','push-b@example.test');
insert into auth.sessions(id,user_id,created_at,updated_at) values ('a6100000-0000-4000-8000-000000000001','a6000000-0000-4000-8000-000000000001',now(),now()),('a6100000-0000-4000-8000-000000000002','a6000000-0000-4000-8000-000000000002',now(),now());
create function pg_temp.registration(generation text) returns jsonb language sql as $$ select jsonb_build_object('action','register','generationId',generation,'installationId','a6200000-0000-4000-8000-000000000001','tokenHash',repeat('a',64),'keyId','v1','subscription',jsonb_build_object('endpoint','https://fcm.googleapis.com/fcm/send/test','p256dh',repeat('x',87),'auth',repeat('x',22))) $$;
select ok(public.web_push_hash_equal(repeat('a',64),repeat('a',64)),'Gleiche Hashes');
select ok(not public.web_push_hash_equal(repeat('a',64),repeat('a',63)||'b'),'Letztes Byte unterschiedlich');
select ok(not public.web_push_hash_equal(null,repeat('a',64)),'Fehlender Hash');
select public.web_push_revoke_binding('a6300000-0000-4000-8000-000000000001',repeat('a',64));
select is(public.web_push_settings('a6000000-0000-4000-8000-000000000001','a6100000-0000-4000-8000-000000000001',pg_temp.registration('a6300000-0000-4000-8000-000000000001'))->>'active','false','Revoke vor Register bleibt terminal');
select is(public.web_push_settings('a6000000-0000-4000-8000-000000000001','a6100000-0000-4000-8000-000000000001',pg_temp.registration('a6300000-0000-4000-8000-000000000001'))->>'active','false','Register Retry reaktiviert nichts');
select is((select count(*) from public.web_push_devices),0::bigint,'Tombstone enthaelt keine Subscription');
select is(public.web_push_settings('a6000000-0000-4000-8000-000000000001','a6100000-0000-4000-8000-000000000001',pg_temp.registration('a6300000-0000-4000-8000-000000000002'))->>'active','true','Register aktiv');
select is(public.web_push_settings('a6000000-0000-4000-8000-000000000001','a6100000-0000-4000-8000-000000000001',pg_temp.registration('a6300000-0000-4000-8000-000000000002'))->>'active','true','Verlorene Antwort idempotent');
select is((select count(*) from public.web_push_devices),1::bigint,'Keine doppelte Subscription');
select throws_ok($$select public.web_push_settings('a6000000-0000-4000-8000-000000000002','a6100000-0000-4000-8000-000000000002',pg_temp.registration('a6300000-0000-4000-8000-000000000002'))$$,'42501','Push binding denied','Fremde Generation nicht uebernehmbar');
select public.web_push_revoke_binding('a6300000-0000-4000-8000-000000000002',repeat('b',64));
select ok((select active from public.web_push_devices where id='a6300000-0000-4000-8000-000000000002'),'Fremdes Token ohne Wirkung');
select is(public.web_push_settings('a6000000-0000-4000-8000-000000000002','a6100000-0000-4000-8000-000000000002',pg_temp.registration('a6300000-0000-4000-8000-000000000003'))->>'active','true','Nutzerwechsel neue Generation');
select ok(not (select active from public.web_push_devices where id='a6300000-0000-4000-8000-000000000002'),'Alte Installation deaktiviert');
select public.web_push_revoke_binding('a6300000-0000-4000-8000-000000000002',repeat('a',64));
select ok((select active from public.web_push_devices where id='a6300000-0000-4000-8000-000000000003'),'Altes Logout widerruft niemals neue Generation');
select throws_ok($$select public.web_push_settings('a6000000-0000-4000-8000-000000000001','a6100000-0000-4000-8000-000000000001','{"action":"revoke","deviceId":"a6300000-0000-4000-8000-000000000003"}')$$,'42501','Push device denied','Fremdes Geraet verweigert');
insert into public.workspaces(id,name) values ('a6400000-0000-4000-8000-000000000001','Push workspace'),('a6400000-0000-4000-8000-000000000002','Foreign workspace');
insert into public.workspace_members(workspace_id,user_id,role) values ('a6400000-0000-4000-8000-000000000001','a6000000-0000-4000-8000-000000000002','member');
select is(public.web_push_allowed_categories('a6000000-0000-4000-8000-000000000002','a6400000-0000-4000-8000-000000000001'),array['order','connection']::text[],'Mitglied bekommt keine Verwaltungsnachrichten');
select is(public.web_push_allowed_categories('a6000000-0000-4000-8000-000000000002','a6400000-0000-4000-8000-000000000002'),'{}'::text[],'Fremder Workspace ohne Kategorien');
select throws_ok($$select public.web_push_settings('a6000000-0000-4000-8000-000000000002','a6100000-0000-4000-8000-000000000002','{"action":"preferences","deviceId":"a6300000-0000-4000-8000-000000000003","workspaceId":"a6400000-0000-4000-8000-000000000002","categories":["order"]}')$$,'42501','Push workspace denied','Fremde Workspacepraeferenz verweigert');
select throws_ok($$select public.web_push_settings('a6000000-0000-4000-8000-000000000002','a6100000-0000-4000-8000-000000000002','{"action":"preferences","deviceId":"a6300000-0000-4000-8000-000000000003","workspaceId":"a6400000-0000-4000-8000-000000000001","categories":["message"]}')$$,'42501','Push category denied','Fehlendes Fachrecht verweigert');
select is(public.web_push_settings('a6000000-0000-4000-8000-000000000001','a6100000-0000-4000-8000-000000000001','{"action":"settings","installationId":"a6200000-0000-4000-8000-000000000001"}')#>>'{binding,active}','false','Reload zeigt Serverdeaktivierung');
select ok(public.web_push_settings('a6000000-0000-4000-8000-000000000002','a6100000-0000-4000-8000-000000000002','{"action":"settings","installationId":"a6200000-0000-4000-8000-000000000001"}')::text not like '%token%' and public.web_push_settings('a6000000-0000-4000-8000-000000000002','a6100000-0000-4000-8000-000000000002','{"action":"settings","installationId":"a6200000-0000-4000-8000-000000000001"}')::text not like '%endpoint%','Settings gibt keine Subscription oder Widerrufsecrets aus');
select is(public.web_push_settings('a6000000-0000-4000-8000-000000000002','a6100000-0000-4000-8000-000000000002','{"action":"settings","installationId":"a6200000-0000-4000-8000-000000000002"}')->'binding','null'::jsonb,'Neue Installation ohne fremde Bindung');
delete from auth.sessions where id='a6100000-0000-4000-8000-000000000002';
select throws_ok($$select public.web_push_settings('a6000000-0000-4000-8000-000000000002','a6100000-0000-4000-8000-000000000002','{"action":"settings","installationId":"a6200000-0000-4000-8000-000000000001"}')$$,'42501','Push session denied','Widerrufene Sitzung verweigert');
select ok(not has_table_privilege('authenticated','public.web_push_devices','select'),'Keine Client Subscription Secrets');
select ok(not has_function_privilege('anon','public.web_push_revoke_binding(uuid,text)','execute'),'Kein direkter anonymer SQL Widerruf');
select * from finish();
rollback;
